const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const link=(u,label,cls='pill-link')=>`<a class="${cls}" href="${esc(u)}" target="_blank" rel="noopener noreferrer">${esc(label)} ↗</a>`;
let subjects=[],subjectById={},user=null,auth=null,db=null,F=null,management=null,currentPage='home',selectedBim=0,teacherRows=[],gradeFilter='todos',gradeSnapshot=null,callableAI=null;
const title=s=>`<div class="page-head"><div><div class="kicker">${esc(s.top||'EXPLORAR // UNIVAP')}</div><h1>${esc(s.h)}</h1><p>${esc(s.p||'')}</p></div>${s.actions||''}</div>`;
function toast(message){const t=$('#toast');t.textContent=message;t.classList.add('show');clearTimeout(window._toastT);window._toastT=setTimeout(()=>t.classList.remove('show'),4100)}
function nav(route){location.hash='#/'+route;$('#sidebar').classList.remove('open');}
function setConnection(s){$('#conn-state').textContent=s;$('.status-dot').style.background=s==='Conectado'?'#48d5a3':'#ffce70'}
function getSub(id){return subjectById[id]}
function courseCount(s){return s.semanas.filter(w=>!w.sem_tema).length}
function visibleSubjects(){return management?.active()&&!management.owner()?management.mine():subjects}
function metaFor(s){return M[s.id]||{emoji:'📚',accent:'#67b7e5',video:s.video||'https://www.youtube.com/results?search_query='+encodeURIComponent(s.nome+' aula'),videoLabel:'Pesquisar videoaulas',pratica:['Prepare uma explicação do tema estudado.','Demonstre um exemplo prático.','Documente o código, o processo e os testes.','Crie um tutorial para outro aluno.','Publique tudo no GitHub.'],projeto:'Projeto Integrador de '+s.nome,brief:'Construa um projeto demonstrativo que integre os conteúdos da disciplina.',deliver:['Funcionalidade reproduzível','Código e materiais no GitHub','README de documentação','Apresentação dos testes'],example:'Crie um protótipo, documente cada etapa e compartilhe com o professor via GitHub.'}}
function doneKey(id,n,i){return `univap-ex-${user?.uid||'anon'}-${id}-${n}-${i}`}
function doneCount(id){let n=0;const s=getSub(id); if(!s)return 0;for(const w of s.semanas){for(let i=0;i<3;i++)if(localStorage.getItem(doneKey(id,w.n,i))==='1')n++}return n}
function progress(s){return Math.round(doneCount(s.id)/Math.max(1,s.semanas.length*3)*100)}
function courseCard(s){const meta=metaFor(s);return `<article class="course-card" style="--accent:${meta.accent}"><div class="course-card-top"><span class="course-icon" aria-hidden="true">${meta.emoji}</span><small>${esc(s.ano)}</small></div><div><h3>${esc(s.nome)}</h3><p>${esc(s.descricao)}</p></div><div class="tag-list"><span class="badge blue">${courseCount(s)} semanas com conteúdo</span><span class="badge">Projeto 0–10</span></div><div class="course-footer"><span>${progress(s)}% de tarefas marcadas</span><a href="#/course/${s.id}">Explorar →</a></div></article>`}
function renderHome(){return `<section class="hero"><div class="hero-copy"><div class="eyebrow">⬛ ${esc(user?.displayName?.split(' ')[0]||'Olá')}, bem-vindo(a) ao seu laboratório digital</div><h1>Aprenda. Construa.<br><em>Suba de nível.</em></h1><p>${subjects.length} disciplinas, aulas por semana, desafios reais e projetos publicados no GitHub. Organize seus estudos e transforme teoria em portfólio.</p><div class="hero-actions"><button class="primary-btn" data-go="courses">Explorar disciplinas ↗</button><button class="outline-btn" data-go="notes">Meu dashboard de notas ▥</button></div></div><div class="pixel-ill" aria-hidden="true"><div class="body"></div><div class="screen"></div><div class="foot"></div><div class="shiny">✦</div><div class="shiny two">✧</div></div></section><div class="stat-grid"><div class="stat"><span class="stat-icon">▦</span><div><strong>${subjects.length}</strong><small>Disciplinas</small></div></div><div class="stat"><span class="stat-icon">▤</span><div><strong>${subjects.reduce((total,s)=>total+s.semanas.length,0)}</strong><small>Semanas organizadas</small></div></div><div class="stat"><span class="stat-icon">★</span><div><strong>${subjects.length}</strong><small>Projetos (0–10)</small></div></div><div class="stat"><span class="stat-icon">☑</span><div><strong>2,0</strong><small>Pontos por lista prática</small></div></div></div><div class="section-heading"><div><div class="kicker">SELECIONE SEU MUNDO</div><h2>Escolha uma disciplina</h2><p>Conteúdo baseado nos planejamentos UNIVAP 2023; TCC com roteiro próprio.</p></div><button class="outline-btn" data-go="courses">Ver todas →</button></div><div class="course-grid">${visibleSubjects().map(courseCard).join('')}</div><div class="notice"><span>🐙</span><div><strong>Regra de ouro: GitHub obrigatório</strong><p>Todos os exercícios semanais, listas práticas e projetos devem estar publicados no GitHub. As entregas são feitas enviando o link do repositório; não vale apenas descrever ou enviar arquivos soltos.</p></div></div><div class="section-heading"><div><div class="kicker">POWER UPS</div><h2>Continue aprendendo</h2></div><button class="outline-btn" data-go="extras">Cursos extras →</button></div><div class="mini-grid">${EXTRAS.slice(0,3).map(x=>`<article class="mini-card"><span style="font-size:28px">${x[3]}</span><h3>${esc(x[0])}</h3><p>${esc(x[1])}</p>${link(x[2],'Abrir curso')}</article>`).join('')}</div>`}
function renderCourses(){return `${title({top:'MAPA DE APRENDIZADO',h:'Todas as disciplinas',p:'Planejamentos organizados em semanas, com material orientado, exercícios e projetos.'})}<div class="notice"><span>📅</span><div><strong>Como funciona o planejamento</strong><p>Os sete componentes originais contemplam 44 semanas, inclusive quatro semanas sem tópico definido nos arquivos de 2023. O TCC tem roteiro complementar de 16 etapas construído a partir do manual da UNIVAP.</p></div></div><div class="course-grid">${visibleSubjects().map(courseCard).join('')}</div>`}
function renderCourse(id){const s=getSub(id);if(!s)return empty('Disciplina não encontrada','Confira o endereço e tente novamente.');const m=metaFor(getSub(id)||{id});return `<div class="course-banner"><span class="course-icon" style="background:${m.accent}23">${m.emoji}</span><div><div class="kicker">${esc(s.ano)} • ${esc(s.origem)}</div><h1>${esc(s.nome)}</h1><p>${esc(s.descricao)}</p></div></div><div class="page-actions"><button class="primary-btn" data-go="apostila/${id}">📚 Abrir apostila</button><button class="outline-btn" data-go="tasks/${id}">☑ Lista e projeto</button><button class="outline-btn" data-submit="${id}:semanal:1">↗ Enviar exercício</button></div><div class="notice"><span>📘</span><div><strong>Como estudar</strong><p>Cada aula inclui objetivos, material complementar, sugestão de videoaula, prática guiada e 3 exercícios ao final. Os vídeos são links externos e, quando não verificados individualmente, são buscas temáticas identificadas. Publique as atividades no GitHub.</p></div></div><div class="bim-tabs">${[0,1,2,3,4].map(b=>`<button data-bim="${b}" class="${selectedBim===b?'active':''}">${b===0?'Todas as semanas':b+'º bimestre'}</button>`).join('')}</div><div class="two-col"><section><div class="section-heading" style="margin-top:0"><h2>Trilha de aulas</h2><span class="badge blue">${s.semanas.length} semanas</span></div><div class="week-list">${s.semanas.filter(w=>!selectedBim||w.bimestre===selectedBim).map(w=>weekCard(s,w)).join('')}</div></section><aside class="aside-stack"><div class="panel"><div class="kicker">AVALIAÇÃO</div><h3>Seu desafio do bimestre</h3><p>Lista prática: até <strong>2,0 pontos</strong>. Projeto da disciplina: nota de <strong>0 a 10</strong>.</p><button class="primary-btn full" data-go="tasks/${id}">Ver enunciados →</button></div><div class="panel"><h3>Material de apoio</h3><p>Apostila digital completa e plano original fornecido pelo professor.</p><button class="outline-btn full" data-go="apostila/${id}">Ler apostila</button><div style="margin-top:9px">${sourceLink(s)}<div class="archive-links">${originalLinks(s)}</div></div></div><div class="panel"><h3>Curso em vídeo</h3><p>Videoaulas e buscas temáticas relacionadas à disciplina.</p>${link(m.video,m.videoLabel)}</div><div class="panel"><h3>Meu progresso</h3><p>${doneCount(id)} de ${s.semanas.length*3} tarefas marcadas como estudadas neste navegador.</p><div style="height:7px;border-radius:7px;background:var(--border);overflow:hidden"><div style="width:${progress(s)}%;height:100%;background:var(--blue)"></div></div><small class="muted">O progresso é local; a entrega oficial ocorre pelo GitHub.</small></div></aside></div>`}
function originalLinks(s){return (ORIGINALS[s.id]||[]).map(f=>link('materiais/planejamentos/'+encodeURIComponent(f),f.toLowerCase().endsWith('xlsm')?'⬇ Planilha Excel (XLSM)':f.includes('assinado')?'⬇ Planejamento assinado (PDF)':'⬇ Planejamento (PDF)')).join('')}
function renderMaterials(){return title({top:'ARQUIVO DO CURSO',h:'Planejamentos e documentos originais',p:'Todos os 21 arquivos presentes no ZIP enviado: planejamentos PDF, versões assinadas e planilhas XLSM.'})+`<div class="notice"><span>📂</span><div><strong>Material didático original</strong><p>Antes de habilitar macros de qualquer planilha XLSM, verifique sua procedência com o professor.</p></div></div>`+subjects.filter(s=>ORIGINALS[s.id]).map(s=>`<div class="panel" style="margin:14px 0"><h3>${esc(s.nome)}</h3><div class="archive-links">${originalLinks(s)}</div></div>`).join('')+`<div class="panel"><h3>Manual de TCC da UNIVAP</h3>${link('materiais/manual-monografia-univap.pdf','⬇ Manual da monografia (PDF)')}</div>`}
function sourceLink(s){if(!s?.planejamento)return '<span class="muted">Material editável pelo professor</span>';const a=s.id==='tcc'?'materiais/manual-monografia-univap.pdf':`materiais/planejamentos/${encodeURIComponent(s.planejamento)}`;return link(a,'⬇ Baixar documento original')}
function weeklyTargets(s,w){return [`Compreender os conceitos e a terminologia de “${w.tema}”.`,`Relacionar o conteúdo às aplicações de ${s.nome}.`,`Produzir um registro prático e documentar o resultado no GitHub.`]}
function weeklyExercises(s,w){if(Array.isArray(w.exercicios)&&w.exercicios.length)return w.exercicios.map(esc);const v=esc(w.tema),m=metaFor(s);switch(s.id){case 'bd':return [`Elabore um exemplo de dados ou tabelas que demonstre o tema: ${v}.`,'Construa um modelo, consulta ou script SQL relacionado ao conteúdo e comente as etapas.','Registre os testes e publique script/diagrama e README no GitHub.'];case 'cldi':return [`Desenhe uma representação lógica ou tabela verdade para: ${v}.`,'Simule pelo menos duas entradas diferentes e analise as saídas.','Documente equações, esquemas e evidências no GitHub.'];case 'cldii':return [`Represente os estados e transições envolvidos em: ${v}.`,'Monte ou simule um circuito sequencial demonstrativo, quando aplicável.','Registre diagrama temporal, capturas e conclusão no GitHub.'];case 'eai':return [`Identifique componentes e grandezas relevantes para: ${v}.`,'Calcule ou simule valores elétricos, informando unidades e medições.','Publique esquema, contas e relatório do experimento no GitHub.'];case 'ps':return [`Faça um esquema ou gráfico que represente: ${v}.`,'Resolva uma aplicação numérica ou compare dois cenários de transmissão.','Registre fórmulas, observações e resultados no GitHub.'];case 'redes':return [`Desenhe uma topologia ou situação real envolvendo: ${v}.`,'Configure ou simule um cenário no Packet Tracer quando aplicável.','Teste, capture as evidências e publique a documentação no GitHub.'];case 'sc':return [`Explique por meio de um diagrama o funcionamento de: ${v}.`,'Realize teste com comandos, máquina virtual ou representação técnica quando aplicável.','Publique capturas, código e análise no GitHub.'];default:return [`Escreva ou revise a parte do TCC referente a: ${v}.`,'Produza uma evidência objetiva, revisão ou diagrama pertinente à etapa.','Atualize o repositório do grupo com documentação e histórico dos commits.']}}
function content(s,w){const m=metaFor(s);return `<h4>📖 Material de aula</h4><p>O assunto desta semana no planejamento é <strong>${esc(w.tema)}</strong>. Estude o conceito central, defina seus termos e analise a aplicação dentro de <strong>${esc(s.nome)}</strong>. Ao concluir, relacione o que foi aprendido com o laboratório ou projeto da disciplina.</p><div class="example"><strong>🔎 Exemplo guiado:</strong><p style="margin:6px 0 0">${esc(m.example)}</p></div><h4>🎯 Objetivos de aprendizagem</h4><ol>${weeklyTargets(s,w).map(x=>`<li>${esc(x)}</li>`).join('')}</ol><h4>🎬 Videoaula / estudo em vídeo</h4><p>Vídeos externos de apoio. O link temático pesquisa o tópico exato desta semana e não representa uma gravação própria do professor.</p>${w.video?link(w.video,'Videoaula desta semana'):link(m.video,m.videoLabel)}${w.material?link(w.material,'Material complementar da semana'):''}${link('https://www.youtube.com/results?search_query='+encodeURIComponent(`${w.tema} aula curso português`),'Buscar vídeo desta semana')}<h4>🧪 Atividade orientada de laboratório</h4><p>Prepare um exemplo reproduzível do tópico, anote ferramentas utilizadas, registre telas ou diagramas e descreva os resultados em um arquivo <code>README.md</code>. Organize o repositório com a pasta <code>semana-${String(w.n).padStart(2,'0')}</code>.</p>`}
function weekCard(s,w){if(w.sem_tema)return `<article class="week-card"><div class="week-btn"><span class="week-num">W${String(w.n).padStart(2,'0')}</span><div><strong>Semana ${w.n}: revisão e orientação</strong><small>Sem tópico definido no planejamento original</small></div><span class="badge">REVISÃO</span></div></article>`;return `<article class="week-card" id="week-${w.n}"><button class="week-btn" data-expand="${w.n}" aria-expanded="false"><span class="week-num">W${String(w.n).padStart(2,'0')}</span><div style="flex:1"><strong>${esc(w.tema)}</strong><small>Semana ${w.n} · ${w.bimestre}º bimestre · ${w.adicionado?'Roteiro complementar':'Planejamento 2023'}</small></div><span class="arr">⌄</span></button><div class="week-detail is-hidden" id="detail-${w.n}"><div class="reading-content">${content(s,w)}</div><h4>✅ Lista de exercícios — final da aula</h4><p class="muted">Faça os três exercícios abaixo. <strong>Todos devem estar publicados no GitHub</strong> e identificados no README do repositório.</p><ol class="exercise-list">${weeklyExercises(s,w).map((q,i)=>`<li><input type="checkbox" data-check="${s.id}:${w.n}:${i}" id="ch-${s.id}-${w.n}-${i}" ${localStorage.getItem(doneKey(s.id,w.n,i))==='1'?'checked':''}><label for="ch-${s.id}-${w.n}-${i}"><b>Exercício ${i+1}.</b> ${q}</label></li>`).join('')}</ol><div class="week-actions"><button class="primary-btn" data-submit="${s.id}:semanal:${w.n}">↗ Enviar pelo GitHub</button><button class="outline-btn" data-go="apostila/${s.id}">📘 Apostila</button></div></div></article>`}
function rubric(id,max){if(max===2)return [['Exercício 1',0.4],['Exercício 2',0.4],['Exercício 3',0.4],['Exercício 4',0.4],['Documentação e GitHub',0.4]];if(id==='tcc')return [['Sistema funcional e demonstração',4],['Monografia conforme o manual',3],['Documentação e repositório',2],['Apresentação e defesa',1]];return [['Funcionalidade e execução',4],['Correção técnica',3],['Código, documentação e GitHub',2],['Apresentação e testes',1]]}
function rubricTable(id,max){return `<table class="rubric"><thead><tr><th>Critério</th><th>Valor máximo</th></tr></thead><tbody>${rubric(id,max).map(([q,n])=>`<tr><td>${esc(q)}</td><td>${n.toLocaleString('pt-BR',{minimumFractionDigits:1})}</td></tr>`).join('')}<tr><td><strong>Total</strong></td><td><strong>${max.toFixed(1).replace('.',',')} pontos</strong></td></tr></tbody></table>`}
function taskCard(s,kind){const m=metaFor(s),pr=kind==='pratica',max=pr?2:10;return `<div class="task-card"><div class="tag-list"><span class="badge ${pr?'green':'red'}">${pr?'LISTA PRÁTICA':'PROJETO'}</span><span class="badge">${max===2?'Até 2,0 pontos':'Nota de 0 a 10'}</span></div><h3>${pr?'Lista prática obrigatória':esc(m.projeto)}</h3><p>${pr?'5 tarefas práticas de 0,4 ponto cada, totalizando até 2 pontos.':esc(m.brief)}</p><ul>${(pr?m.pratica:m.deliver).map(a=>`<li>${esc(a)}</li>`).join('')}</ul><div><strong style="font-size:12px">Critérios de avaliação</strong>${rubricTable(s.id,max)}</div><div class="task-footer"><span class="badge blue">GITHUB OBRIGATÓRIO</span><button class="primary-btn" data-submit="${s.id}:${kind}:1">↗ Enviar link</button></div></div>`}
function renderTasks(id){const items=id&&getSub(id)?[getSub(id)]:visibleSubjects();return `${title({top:'DESAFIOS DE APRENDIZAGEM',h:id?getSub(id).nome:'Atividades e projetos',p:'Cada disciplina possui lista prática obrigatória de até 2 pontos e projeto próprio avaliado de 0 a 10.',actions:'<button class="outline-btn" data-go="guide">Como entregar no GitHub</button>'})}<div class="notice"><span>⚠️</span><div><strong>Entrega exclusivamente por link do GitHub</strong><p>Todos os exercícios práticos, trabalhos, projetos, códigos e evidências devem estar no GitHub. Inclua README.md, código-fonte, documentação, capturas ou simulações. Depois envie o link no formulário do portal.</p></div></div>${(management?.renderPosted(id)||'')}${items.map(s=>`<div class="section-heading"><div><h2>${metaFor(s).emoji} ${esc(s.nome)}</h2><p>Enunciados, critérios e entrega por repositório.</p></div><button class="outline-btn" data-go="course/${s.id}">Voltar às aulas →</button></div><div class="task-grid">${taskCard(s,'pratica')}${taskCard(s,'projeto')}</div>`).join('')}`}
function tccChecklist(){return `<h3>Estrutura obrigatória conforme o manual UNIVAP</h3><div class="mini-grid"><div class="mini-card"><span class="badge blue">PRÉ-TEXTUAIS</span><ul><li>Capa</li><li>Folha de rosto</li><li>Folha de aprovação (após banca)</li><li>Dedicatória</li><li>Agradecimentos</li><li>Resumo em português e palavras-chave</li><li>Sumário</li></ul></div><div class="mini-card"><span class="badge blue">TEXTUAIS</span><ul><li>Introdução: tema, problema e objetivos</li><li>Metodologia e desenvolvimento</li><li>Diagramas, tecnologias e custos</li><li>Resultados e discussões</li><li>Conclusão</li></ul></div><div class="mini-card"><span class="badge blue">PÓS-TEXTUAIS</span><ul><li>Referências bibliográficas</li><li>Anexo: manual do usuário</li><li>Documentação técnica</li><li>Arquivos-fonte do sistema</li><li>Manual de instalação</li></ul></div></div><div class="panel" style="margin-top:18px"><h3>Formatação exigida pelo manual</h3><table class="rubric"><tbody><tr><td>Papel</td><td>A4 (21 × 29,7 cm)</td></tr><tr><td>Margens</td><td>Esq./superior: 3 cm; dir./inferior: 2 cm</td></tr><tr><td>Fonte</td><td>Times New Roman 12, texto preto</td></tr><tr><td>Texto</td><td>Justificado, entrelinhas 1,5</td></tr><tr><td>Citações longas/notas</td><td>Espaço simples, tamanho reduzido</td></tr><tr><td>Resumo</td><td>Até 500 palavras</td></tr><tr><td>Capa final encadernada</td><td>Preta com letras douradas, após defesa</td></tr></tbody></table><p><small>Observação: estas regras refletem o manual fornecido (que faz referência a normas ABNT de sua época). Confira eventuais atualizações com a coordenação antes da entrega oficial.</small></p></div>`}
function renderTcc(){return `${title({top:'MISSÃO FINAL // TERCEIRO ANO',h:'TCC & Monografia',p:'Sistema, pesquisa, documentação e defesa — baseados no Manual de Monografia do Técnico em Informática.',actions:`${sourceLink(getSub('tcc'))}`})}<div class="hero" style="min-height:200px"><div class="hero-copy"><div class="eyebrow">MISSÃO: ENTREGA FINAL</div><h1 style="font-size:clamp(26px,3vw,39px)">Do primeiro protótipo<br>à banca avaliadora.</h1><p>Siga os passos do manual e entregue evidências de um sistema funcional.</p><button class="primary-btn" data-go="course/tcc">Ver as 16 etapas →</button></div><div class="pixel-ill" aria-hidden="true"><div class="body"></div><div class="screen"></div><div class="foot"></div></div></div><div class="section-heading"><h2>Checklist da monografia</h2><span class="badge blue">Manual original • 25 páginas</span></div>${tccChecklist()}<div class="section-heading"><h2>Entregas do TCC</h2></div><div class="task-grid">${taskCard(getSub('tcc'),'pratica')}${taskCard(getSub('tcc'),'projeto')}</div>`}
function renderApostila(id){const s=getSub(id);if(!s)return empty('Apostila não encontrada','');const m=metaFor(getSub(id)||{id});return `${title({top:'BIBLIOTECA DIGITAL',h:'Apostila • '+s.nome,p:'Material complementar autoral estruturado com base nos temas do planejamento. Inclui as listas de exercícios de cada semana.',actions:`<button class="primary-btn" data-download="${id}">⬇ Baixar apostila HTML</button><button class="outline-btn" data-print>🖨 Imprimir / PDF</button>`})}<div class="notice"><span>📚</span><div><strong>Guia de estudo</strong><p>Esta apostila digital compila a trilha, os objetivos, exemplos e exercícios de cada semana. Para um aprofundamento teórico, consulte as videoaulas e referências complementares indicadas em cada capítulo.</p></div></div>${[1,2,3,4].map(b=>`<section class="panel" style="margin:17px 0"><div class="kicker">CAPÍTULO ${b}</div><h2>${b}º bimestre</h2>${s.semanas.filter(w=>w.bimestre===b&&!w.sem_tema).map(w=>`<div class="reading-content" style="padding:18px 0;border-bottom:1px solid var(--border)"><h3>Semana ${w.n}: ${esc(w.tema)}</h3>${content(s,w)}<h4>Exercícios de fixação</h4><ol>${weeklyExercises(s,w).map(x=>`<li>${x}</li>`).join('')}</ol></div>`).join('')||'<p>Sem tema definido no planejamento fornecido.</p>'}</section>`).join('')}<div class="panel"><h3>Referências para aprofundamento</h3><p>${link(m.video,m.videoLabel)}${link('https://github.com/skills/introduction-to-github','GitHub Skills')}</p><p>Disciplina: ${esc(s.nome)}. Fonte do planejamento: ${esc(s.origem)}.</p></div>`}
function createApostila(id){const s=getSub(id),m=metaFor(getSub(id)||{id});if(!s)return;const contentText=`<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><title>Apostila - ${esc(s.nome)}</title><style>body{font:15px/1.65 Georgia,serif;color:#171d27;max-width:790px;margin:50px auto;padding:0 25px}h1,h2,h3{font-family:Arial,sans-serif;color:#123d7e}h1{font-size:30px}h2{border-bottom:2px solid #2862ac;padding-bottom:8px;margin-top:45px}h3{margin-top:28px}.note{background:#e9f1fd;padding:18px;border-left:4px solid #2e6bd2}@media print{body{margin:0;max-width:none}h2,h3{break-after:avoid}section{break-inside:avoid}}</style></head><body><h1>Apostila • ${esc(s.nome)}</h1><p>Portal Pixel Academy — Prof. Bruno Michel Pera / UNIVAP.</p><p>Material didático complementar, baseado em ${esc(s.origem)}. Para entregar exercícios, publique o resultado no GitHub.</p>${[1,2,3,4].map(b=>`<h2>${b}º Bimestre</h2>`+s.semanas.filter(w=>w.bimestre===b&&!w.sem_tema).map(w=>`<section><h3>Semana ${w.n} — ${esc(w.tema)}</h3><p>Conteúdo estudado: ${esc(w.tema)}. Objetivo: compreender seus fundamentos, explorar aplicações na disciplina e demonstrar o aprendizado de forma prática.</p><div class="note"><strong>Exemplo orientado:</strong> ${esc(m.example)}</div><h4>Exercícios da aula</h4><ol>${weeklyExercises(s,w).map(x=>`<li>${x}</li>`).join('')}</ol></section>`).join('')).join('')}<p>Fonte: ${esc(s.origem)}.</p></body></html>`;const a=document.createElement('a');const url=URL.createObjectURL(new Blob([contentText],{type:'text/html;charset=utf-8'}));a.href=url;a.download=`Apostila_UNIVAP_${id.toUpperCase()}.html`;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);toast('Apostila HTML gerada. Você pode abri-la ou imprimir em PDF.');}
function renderExtras(){return `${title({top:'EXPLORE • LEARN • BUILD',h:'Cursos extras',p:'Trilhas complementares para ampliar seu repertório e fortalecer seu portfólio.'})}<div class="notice"><span>🎮</span><div><strong>Desafio extra: SumoBotStudio</strong><p>Experimente o simulador de robôs criado pelo professor. Aplique lógica, sensores, programação e estratégia em desafios interativos.</p>${link('https://perabru.github.io/SumoBotStudio/','Acessar SumoBotStudio')}</div></div><div class="resource-grid">${EXTRAS.map(x=>`<article class="resource-card"><span class="resource-icon">${x[3]}</span><span class="badge blue">${esc(x[4])}</span><strong>${esc(x[0])}</strong><p>${esc(x[1])}</p>${link(x[2],'Acessar curso')}</article>`).join('')}</div><div class="notice"><span>ℹ️</span><div><strong>Catálogo Drive de Pobre</strong><p>O endereço solicitado está incluído como referência externa, mas não foi possível verificar os cursos específicos do catálogo. Para GitHub, priorizamos os cursos gratuitos e oficialmente acessíveis acima.</p></div></div>`}
function renderTools(){return `${title({top:'KIT DO DESENVOLVEDOR',h:'Downloads e ferramentas',p:'Instaladores, ambientes e serviços oficiais para os laboratórios das disciplinas.'})}<div class="resource-grid">${TOOLS.map(t=>`<article class="resource-card"><span class="resource-icon">${t[3]}</span><strong>${esc(t[0])}</strong><p>${esc(t[1])}</p>${link(t[2],'Abrir download oficial')}</article>`).join('')}</div><div class="notice"><span>🔐</span><div><strong>Instale com segurança</strong><p>Os botões levam aos sites oficiais; versões e licenças podem mudar. Use equipamentos autorizados e siga as orientações do laboratório.</p></div></div>`}
function renderGuide(){const steps=[['Crie uma conta e um repositório','Entre em github.com, crie um repositório público com nome da disciplina e ative um README.'],['Organize suas pastas','Use pastas como semana-01/, semana-02/, lista-pratica/ e projeto/. Inclua código-fonte, esquemas e imagens.'],['Faça commits frequentes','Cada avanço deve ter commit com mensagem explicativa; não envie somente um ZIP sem histórico.'],['Documente no README.md','Explique objetivo, tecnologias, instalação, como executar, testes e autores. Inclua capturas e resultados.'],['Copie o link do repositório','Exemplo: https://github.com/usuario/projeto-disciplina. Confira se o link abre sem pedir permissão.'],['Envie no portal','Clique em Enviar atividade, informe disciplina, tipo, semana (quando aplicável) e o endereço do GitHub.']];return `${title({top:'REGRAS DE ENTREGA',h:'Guia rápido do GitHub',p:'Todas as atividades devem estar publicadas e documentadas antes do envio.'})}<div class="two-col"><div><div class="guide-steps">${steps.map((x,i)=>`<div class="guide-step"><span>${String(i+1).padStart(2,'0')}</span><div><h3>${esc(x[0])}</h3><p>${esc(x[1])}</p></div></div>`).join('')}</div></div><aside class="aside-stack"><div class="panel"><h3>Checklist antes da entrega</h3><ul><li>Repositório público no GitHub</li><li>Código ou simulação executável</li><li>README com instruções e resultados</li><li>Capturas e evidências quando aplicável</li><li>Link testado em janela anônima</li><li>Disciplina e tarefa identificadas</li></ul><button class="primary-btn full" data-submit="bd:pratica:1">Enviar atividade</button></div><div class="panel"><h3>Aprenda Git e GitHub</h3>${link('https://www.cursoemvideo.com/curso/curso-de-git-e-github/','Curso gratuito – Curso em Vídeo')}${link('https://github.com/skills/introduction-to-github','GitHub Skills – Introdução')}${link(videoGit,'Videoaulas do curso')}</div></aside></div>`}
function empty(h,p){return `<div class="empty-state"><b>▤</b><h3>${esc(h)}</h3><p>${esc(p)}</p><button class="primary-btn" data-go="home">Voltar ao início</button></div>`}
function myDate(ts){if(!ts)return 'Data indisponível';return new Date(ts).toLocaleString('pt-BR',{dateStyle:'short',timeStyle:'short'})}
function submissionLabel(o){const s=getSub(o.disciplina);return `${s?.nome||o.disciplina} · ${o.tipo==='pratica'?'Lista prática (até 2 pontos)':o.tipo==='projeto'?'Projeto (0–10)':`Semana ${o.semana}`}`}
function viewSubmission(uid,key,o,grade,teacher=false){const at=management?.getPost(o.atividadeId),max=Number(at?.notaMax??(o.tipo==='pratica'?2:10));return `<div class="submission-row"><div style="min-width:0"><strong>${esc(submissionLabel(o))}</strong><small>${esc(o.nome||'Aluno')} · ${myDate(o.criadoEm)}</small><div>${link(o.github,'Ver repositório GitHub')}</div>${o.comentario?`<p style="font-size:12px;margin:8px 0">${esc(o.comentario)}</p>`:''}${grade?`<p style="font-size:12px;margin:5px 0">📝 <b>Professor:</b> ${esc(grade.comentario||'Avaliado')}</p>`:''}${teacher?`<div class="grade-area"><label>Nota <input type="number" min="0" max="${max}" step="0.1" id="nota-${key}" value="${grade?.nota??''}" aria-label="Nota"></label><textarea rows="1" id="feedback-${key}" placeholder="Feedback ao aluno">${esc(grade?.comentario||'')}</textarea><button class="primary-btn" data-grade="${uid}:${key}:${max}">Salvar</button></div>`:''}</div><div class="submission-meta">${grade?`<span class="badge green">${Number(grade.nota).toFixed(1).replace('.',',')} / ${max.toFixed(1).replace('.',',')}</span>`:'<span class="badge blue">Enviado</span>'}</div></div>`}

async function renderNotes(force=false){
 const view=$('#view');view.innerHTML=title({top:'MINHAS NOTAS // DASHBOARD',h:'Consultando seu boletim',p:'Carregando notas e feedback do Firebase...'});
 if(!db||!F){view.innerHTML=empty('Banco de dados indisponível','Ative o Firebase para consultar suas notas.');return}
 try{
  if(force||!gradeSnapshot||gradeSnapshot.uid!==user.uid){
    const [subs,notes,posted]=await Promise.all([F.get(F.ref(db,`${DB_ROOT}/submissoes/${user.uid}`)),F.get(F.ref(db,`${DB_ROOT}/avaliacoes/${user.uid}`)),F.get(F.ref(db,`${DB_ROOT}/atividades`))]);
    gradeSnapshot={uid:user.uid,submissions:subs.val()||{},grades:notes.val()||{},posts:posted.val()||{}};
  }
  view.innerHTML=renderStudentGradeDashboard({subjects:visibleSubjects(),...gradeSnapshot,filter:gradeFilter,studentName:management.profile()?.nome||user.displayName||'Estudante'});
 }catch(e){view.innerHTML=empty('Não foi possível carregar as notas',e?.message||'Verifique as regras do Firebase.');}
}

async function renderSubmissions(){const root=$('#view');root.innerHTML=title({top:'MINHAS ENTREGAS',h:'Atividades enviadas',p:'Os links submetidos ficam registrados no Firebase, vinculados à sua conta Google.',actions:'<button class="primary-btn" data-submit="bd:pratica:1">+ Nova entrega</button>'})+empty('Consultando suas atividades...','');if(!db||!F){root.innerHTML+=`<div class="notice"><span>⚠</span><div><strong>Banco de dados indisponível</strong><p>Configure o Firebase e as regras do Realtime Database.</p></div></div>`;return}try{const [ss,gg]=await Promise.all([F.get(F.ref(db,`${DB_ROOT}/submissoes/${user.uid}`)),F.get(F.ref(db,`${DB_ROOT}/avaliacoes/${user.uid}`))]);const entries=Object.entries(ss.val()||{}).sort((a,b)=>(b[1].criadoEm||0)-(a[1].criadoEm||0));const grades=gg.val()||{};root.innerHTML=title({top:'MINHAS ENTREGAS',h:'Atividades enviadas',p:'Os links submetidos ficam registrados no Firebase, vinculados à sua conta Google.',actions:'<button class="primary-btn" data-submit="bd:pratica:1">+ Nova entrega</button>'})+(entries.length?entries.map(([key,o])=>viewSubmission(user.uid,key,o,grades[key])).join(''):empty('Nenhuma atividade enviada','Use o formulário para enviar o link do seu repositório GitHub.'))}catch(e){root.innerHTML+=`<div class="notice"><span>⚠</span><div><strong>Não foi possível carregar as entregas</strong><p>${esc(e.message)}. Confira as regras do banco de dados no arquivo SETUP-FIREBASE.md.</p></div></div>`}}
async function renderTeacher(){if(user?.email?.toLowerCase()!==TEACHER_EMAIL){$('#view').innerHTML=empty('Acesso restrito','Este painel é exclusivo do professor.');return}const root=$('#view');root.innerHTML=title({top:'ÁREA DO PROFESSOR',h:'Correção de atividades',p:'Confira os links enviados e atribua feedback e notas.'})+empty('Carregando registros...','');try{const [ss,gg]=await Promise.all([F.get(F.ref(db,`${DB_ROOT}/submissoes`)),F.get(F.ref(db,`${DB_ROOT}/avaliacoes`))]);const sub=ss.val()||{},notes=gg.val()||{};teacherRows=Object.entries(sub).flatMap(([uid,rows])=>Object.entries(rows||{}).map(([key,o])=>({uid,key,o,grade:notes?.[uid]?.[key]}))).sort((a,b)=>(b.o.criadoEm||0)-(a.o.criadoEm||0));root.innerHTML=title({top:'ÁREA DO PROFESSOR',h:'Correção de atividades',p:`${teacherRows.length} entrega(s) encontradas. O acesso depende das regras de segurança do Firebase.`})+`<div class="toolbar"><input class="search" id="teacher-search" placeholder="Buscar por nome, disciplina ou atividade..."><span class="badge blue">${teacherRows.length} entregas</span></div><div id="teacher-results">${teacherRows.length?teacherRows.map(x=>viewSubmission(x.uid,x.key,x.o,x.grade,true)).join(''):empty('Nenhuma atividade recebida','Os links dos alunos aparecerão aqui.')}</div>`}catch(e){root.innerHTML=title({h:'Painel do professor',p:'O Firebase precisa permitir leitura global de entregas para sua conta.'})+`<div class="notice"><span>⚠</span><div><strong>Não foi possível carregar o painel</strong><p>${esc(e.message)}. Mescle as regras de segurança em SETUP-FIREBASE.md.</p></div></div>`}}
async function saveGrade(code){const [uid,key,maxStr]=code.split(':'),max=Number(maxStr),n=Number($('#nota-'+key)?.value),feedback=$('#feedback-'+key)?.value.trim()||'';if(!Number.isFinite(n)||n<0||n>max||$('#nota-'+key).value.trim()===''){toast(`Informe uma nota entre 0 e ${max}.`);return}try{await F.set(F.ref(db,`${DB_ROOT}/avaliacoes/${uid}/${key}`),{nota:n,comentario:feedback,avaliadoEm:Date.now(),professor:user.email});toast('Nota e feedback salvos.');await renderTeacher()}catch(e){toast('Erro ao salvar nota: '+e.message)}}
function showModal(spec='bd:pratica:1'){const [id,typ,week]=spec.split(':'),s=getSub(id)||visibleSubjects()[0]||subjects[0];$('#sub-course').innerHTML=visibleSubjects().map(x=>`<option value="${x.id}">${esc(x.nome)}</option>`).join('');$('#sub-course').value=s.id;$('#sub-type').value=typ||'pratica';fillWeeks(Number(week)||1);$('#sub-url').value='';$('#sub-note').value='';$('#form-message').textContent='';$('#submit-modal').showModal()}
function fillWeeks(preselected=1){const s=getSub($('#sub-course').value)||visibleSubjects()[0];if(!s)return;$('#sub-week').innerHTML=s.semanas.filter(w=>!w.sem_tema).map(w=>`<option value="${w.n}">Semana ${w.n}: ${esc(w.tema.slice(0,52))}</option>`).join('');$('#sub-week').value=preselected;$('#week-wrap').classList.toggle('is-hidden',$('#sub-type').value!=='semanal');const posts=management?.activityChoices(s.id,$('#sub-type').value)||'';$('#sub-activity').innerHTML='<option value="">Lista/projeto fixo ou exercício da semana</option>'+posts;$('#sub-activity-wrap').classList.toggle('is-hidden',!posts)}
function isGitHubUrl(u){try{const x=new URL(u);return x.protocol==='https:'&&(/(^|\.)github\.com$/.test(x.hostname)||/(^|\.)github\.io$/.test(x.hostname))&&x.pathname.split('/').filter(Boolean).length>=2}catch{return false}}
async function sendSubmission(e){e.preventDefault();$('#form-message').textContent='';if(!user||!db||!F||!management?.active()){$('#form-message').textContent='Faça login com matrícula aprovada para enviar.';return}const github=$('#sub-url').value.trim(),comment=$('#sub-note').value.trim(),s=getSub($('#sub-course').value),typ=$('#sub-type').value,atividadeId=$('#sub-activity').value||'';if(!s||!visibleSubjects().some(x=>x.id===s.id)){$('#form-message').textContent='Disciplina não autorizada para sua matrícula.';return}if(!isGitHubUrl(github)){$('#form-message').textContent='Use HTTPS: https://github.com/usuario/repositorio';return}if(comment.length>750){$('#form-message').textContent='O comentário pode ter no máximo 750 caracteres.';return}const btn=$('#submit-btn');btn.disabled=true;btn.textContent='Enviando...';try{const ref=F.push(F.ref(db,`${DB_ROOT}/submissoes/${user.uid}`));await F.set(ref,{disciplina:s.id,tipo:typ,semana:typ==='semanal'?Number($('#sub-week').value):null,atividadeId,github,comentario:comment,nome:management.profile()?.nome||user.displayName||user.email,email:user.email,criadoEm:Date.now()});$('#submit-modal').close();gradeSnapshot=null;toast('Entrega registrada no Firebase!');nav('submissions')}catch(err){$('#form-message').textContent=`Não foi possível registrar: ${err.message}. Confira as regras do Firebase.`}finally{btn.disabled=false;btn.textContent='↗ Enviar atividade'}}
function updateNav(){const p=currentPage==='course'||currentPage==='apostila'?'courses':currentPage;document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.page===p));$('#teacher-nav').classList.toggle('is-hidden',!management?.owner())}
async function render(){if(!user||!management)return;const parts=(location.hash||'#/home').slice(2).split('/').filter(Boolean);currentPage=parts[0]||'home';$('#breadcrumb').innerHTML=`UNIVAP <span>/</span> ${esc(currentPage.toUpperCase())}`;updateNav();const view=$('#view');document.body.classList.toggle('onboarding',!management.active());if(!management.active()){view.innerHTML=management.renderGate();return}if(!management.owner()&&['teacher'].includes(currentPage)){nav('home');return}if(!management.owner()&&['course','apostila','tasks'].includes(currentPage)&&parts[1]&&!visibleSubjects().some(x=>x.id===parts[1])){view.innerHTML=empty('Sem matrícula nesta disciplina','Edite seu perfil para solicitar acesso a ela.');return}if(currentPage==='home')view.innerHTML=renderHome();else if(currentPage==='courses')view.innerHTML=renderCourses();else if(currentPage==='course'){selectedBim=0;view.innerHTML=renderCourse(parts[1]);}else if(currentPage==='tasks')view.innerHTML=renderTasks(parts[1]);else if(currentPage==='tcc')view.innerHTML=renderTcc();else if(currentPage==='apostila')view.innerHTML=renderApostila(parts[1]);else if(currentPage==='tools')view.innerHTML=renderTools();else if(currentPage==='materials')view.innerHTML=renderMaterials();else if(currentPage==='extras')view.innerHTML=renderExtras();else if(currentPage==='guide')view.innerHTML=renderGuide();else if(currentPage==='profile')view.innerHTML=management.renderProfile();else if(currentPage==='submissions')await renderSubmissions();else if(currentPage==='notes')await renderNotes();else if(currentPage==='teacher')view.innerHTML=await management.renderAdmin();else view.innerHTML=empty('Página não encontrada','');window.scrollTo({top:0,behavior:'instant'});}
function bootUI(){document.querySelectorAll('[data-page]').forEach(b=>b.addEventListener('click',()=>nav(b.dataset.page)));$('#menu-toggle').addEventListener('click',()=>$('#sidebar').classList.toggle('open'));$('#theme-btn').addEventListener('click',()=>{const light=document.body.dataset.theme!=='light';document.body.dataset.theme=light?'light':'dark';localStorage.setItem('univap-theme',document.body.dataset.theme);$('#theme-ico').textContent=light?'☀':'☾'});const mode=localStorage.getItem('univap-theme');if(mode==='light'){$('body').dataset.theme='light';$('#theme-ico').textContent='☀'}$('#logout-btn').addEventListener('click',async()=>{if(auth&&F)await F.signOut(auth);toast('Você saiu da conta.')});$('#modal-close').onclick=$('#cancel-submit').onclick=()=>$('#submit-modal').close();$('#sub-course').addEventListener('change',()=>fillWeeks());$('#sub-type').addEventListener('change',()=>fillWeeks());$('#submit-form').addEventListener('submit',sendSubmission);window.addEventListener('hashchange',render);$('#view').addEventListener('submit',async e=>{if(management)await management.handleSubmit(e)});$('#view').addEventListener('change',async e=>{if(management&&await management.handleChange(e))return;const code=e.target.dataset.check;if(code){const [id,n,i]=code.split(':');localStorage.setItem(doneKey(id,n,i),e.target.checked?'1':'0')}});$('#view').addEventListener('input',e=>{if(management?.handleInput(e))return});$('#view').addEventListener('click',async e=>{if(management&&await management.handleClick(e))return;const b=e.target.closest('button');if(!b)return;if(b.dataset.go){nav(b.dataset.go);return}if(b.dataset.submit){showModal(b.dataset.submit);return}if(b.hasAttribute('data-expand')){const n=b.dataset.expand,target=$('#detail-'+n),expand=target.classList.contains('is-hidden');target.classList.toggle('is-hidden');b.setAttribute('aria-expanded',expand?'true':'false');return}if(b.hasAttribute('data-bim')){selectedBim=Number(b.dataset.bim);$('#view').innerHTML=renderCourse(location.hash.split('/')[2]);return}if(b.dataset.download){createApostila(b.dataset.download);return}if(b.hasAttribute('data-print')){window.print();return}if(b.dataset.grade){await saveGrade(b.dataset.grade);return}if(b.dataset.gradeFilter){gradeFilter=b.dataset.gradeFilter;await renderNotes();return}if(b.hasAttribute('data-notes-refresh')){await renderNotes(true);return}});initInstallPrompt()}
async function start(){try{subjects=await loadCurriculum();subjectById=Object.fromEntries(subjects.map(x=>[x.id,x]));bootUI();setConnection('Inicializando...');const base='https://www.gstatic.com/firebasejs/13.3.0/';const [appMod,authMod,dbMod]=await Promise.all([import(base+'firebase-app.js'),import(base+'firebase-auth.js'),import(base+'firebase-database.js')]);F={...authMod,...dbMod};const app=appMod.initializeApp(FIREBASE_CONFIG);auth=authMod.getAuth(app);db=dbMod.getDatabase(app);try{const fnMod=await import(base+'firebase-functions.js');const functions=fnMod.getFunctions(app,'us-central1');callableAI=fnMod.httpsCallable(functions,'corrigirEntregaGemini',{timeout:120000});}catch(e){console.warn('Função de correção IA indisponível',e);}management=createManagement({user:()=>user,db:()=>db,F:()=>F,subjects:()=>subjects,setSubjects:arr=>{subjects=arr;subjectById=Object.fromEntries(arr.map(x=>[x.id,x]))},render,toast,showModal,setSubmissionActivity:id=>{$('#sub-activity').value=id},signOut:()=>authMod.signOut(auth),aiGrade:async(uid,submissionId)=>{if(!callableAI)throw new Error('O serviço Gemini ainda não foi configurado no Firebase Functions.');const res=await callableAI({uid,submissionId});return res.data;}});await authMod.setPersistence(auth,authMod.browserLocalPersistence);$('#login-btn').addEventListener('click',async()=>{const b=$('#login-btn');b.disabled=true;$('#login-help').textContent='';try{await authMod.signInWithPopup(auth,new authMod.GoogleAuthProvider())}catch(e){if(e.code==='auth/popup-blocked'||e.code==='auth/operation-not-supported-in-this-environment'){await authMod.signInWithRedirect(auth,new authMod.GoogleAuthProvider())}else{$('#login-help').textContent=errorMsg(e);b.disabled=false}}});await authMod.getRedirectResult(auth).catch(()=>null);authMod.onAuthStateChanged(auth,async u=>{gradeSnapshot=null;user=u;if(u){$('#user-name').textContent=u.displayName||u.email||'Aluno(a)';$('#user-avatar').textContent=(u.displayName||'A').slice(0,1).toUpperCase();$('#login-screen').classList.add('is-hidden');$('#app-shell').classList.remove('is-hidden');setConnection('Conectado');await management.init(u);await render()}else{$('#app-shell').classList.add('is-hidden');$('#login-screen').classList.remove('is-hidden');setConnection('Aguardando login');$('#login-btn').disabled=false}})}catch(err){console.error(err);$('#login-screen').classList.remove('is-hidden');$('#login-help').textContent='Não foi possível iniciar o portal: '+err.message;setConnection('Erro de configuração')}finally{setTimeout(()=>$('#splash').classList.add('fade'),300);setTimeout(()=>$('#splash').remove(),850)}if('serviceWorker'in navigator)navigator.serviceWorker.register('./service-worker.js').catch(console.warn)}
function errorMsg(e){if(e.code==='auth/unauthorized-domain')return 'Domínio não autorizado no Firebase. No console, adicione perabru.github.io em Authentication → Configurações → Domínios autorizados.';if(e.code==='auth/operation-not-allowed')return 'Ative o provedor Google em Firebase Authentication → Métodos de login.';if(e.code==='auth/popup-closed-by-user')return 'Login cancelado. Clique novamente para tentar.';return `Falha na autenticação: ${e.message}`}
let deferredInstall=null;
function initInstallPrompt(){const btn=$('#install-btn');const hint=$('#install-hint');if(!btn)return;window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredInstall=e;btn.classList.remove('is-hidden')});btn.addEventListener('click',async()=>{if(deferredInstall){deferredInstall.prompt();await deferredInstall.userChoice;deferredInstall=null;btn.classList.add('is-hidden')}else{toast('Android: menu do navegador → Instalar app. iPhone: Compartilhar → Adicionar à Tela de Início.')}});window.addEventListener('appinstalled',()=>{btn.classList.add('is-hidden');toast('Pixel Academy instalado neste dispositivo!')});if(hint)hint.addEventListener('click',()=>toast('iPhone: Safari → Compartilhar → Adicionar à Tela de Início. Android: Chrome → Instalar app.'));}
start();
